func (c *Config) credentials() *cliutil.Credentials {
	return &cliutil.Credentials{
		BaseURL:               c.BaseURL,
		AuthHeaderVal:         c.AuthHeaderVal,
		AccessToken:           c.AccessToken,
		RefreshToken:          c.RefreshToken,
		TokenExpiry:           c.TokenExpiry,
		ClientID:              c.ClientID,
		ClientSecret:          c.ClientSecret,
		RichAuthApiKey:        c.RichAuthApiKey,
		RichAuthClientId:      c.RichAuthClientId,
		RichAuthClientSecret:  c.RichAuthClientSecret,
		RichAuthSessionCookie: c.RichAuthSessionCookie,
		RichAuthOptionalToken: c.RichAuthOptionalToken,
		RichAuthBotToken:      c.RichAuthBotToken,
		RichAuthUserToken:     c.RichAuthUserToken,
	}
}

func (c *Config) applyCredentials(creds *cliutil.Credentials) {
	if creds == nil {
		return
	}
	if c.AuthHeaderVal == "" {
		c.AuthHeaderVal = creds.AuthHeaderVal
	}
	if c.AccessToken == "" {
		c.AccessToken = creds.AccessToken
	}
	if c.RefreshToken == "" {
		c.RefreshToken = creds.RefreshToken
	}
	if c.TokenExpiry.IsZero() {
		c.TokenExpiry = creds.TokenExpiry
	}
	if c.ClientID == "" {
		c.ClientID = creds.ClientID
	}
	if c.ClientSecret == "" {
		c.ClientSecret = creds.ClientSecret
	}
	if c.RichAuthApiKey == "" {
		c.RichAuthApiKey = creds.RichAuthApiKey
	}
	if c.RichAuthClientId == "" {
		c.RichAuthClientId = creds.RichAuthClientId
	}
	if c.RichAuthClientSecret == "" {
		c.RichAuthClientSecret = creds.RichAuthClientSecret
	}
	if c.RichAuthSessionCookie == "" {
		c.RichAuthSessionCookie = creds.RichAuthSessionCookie
	}
	if c.RichAuthOptionalToken == "" {
		c.RichAuthOptionalToken = creds.RichAuthOptionalToken
	}
	if c.RichAuthBotToken == "" {
		c.RichAuthBotToken = creds.RichAuthBotToken
	}
	if c.RichAuthUserToken == "" {
		c.RichAuthUserToken = creds.RichAuthUserToken
	}
}

func (c *Config) credentialsFilePath() (string, error) {
	if c.explicitConfig {
		return cliutil.CredentialsFilePathForConfig(c.Path)
	}
	return cliutil.CredentialsFilePath()
}

func (c *Config) saveCredentialsFirst(credsPath string) error {
	if c.AgentcookieManagedByExternalStore() {
		c.markAgentcookieManaged()
		return nil
	}
	persisted := c.configForSave()
	var err error
	if c.explicitConfig {
		err = cliutil.SaveExplicitCredentials(credsPath, persisted.credentials())
	} else {
		err = cliutil.SaveCredentials(persisted.credentials())
	}
	if err != nil {
		return err
	}
	c.CredentialSource = "credentials file"
	return nil
}

type credentialsSnapshot struct {
	path          string
	data          []byte
	perm          os.FileMode
	symlinkTarget string
	missing       bool
}

// credentialSaveBeforeLockHook runs after the lock path is chosen and before
// it is acquired. Tests move a symlink in that window.
var credentialSaveBeforeLockHook func()

// Credentials and config are separate files. Publishing tokens first would
// otherwise leave a new credentials.toml if the config write fails.
func (c *Config) saveCredentialsThenConfig() error {
	requested := c.Path
	if c.explicitConfig {
		resolved, err := cliutil.ResolveConfigFilePath(requested)
		if err != nil {
			return err
		}
		if err := os.MkdirAll(filepath.Dir(resolved), 0o700); err != nil {
			return err
		}
	}
	// Resolve again now that the profile directory exists so the lock matches
	// a reload through the same path.
	_, _, lockPath, err := c.credentialSavePlan(requested)
	if err != nil {
		return err
	}
	if !c.explicitConfig {
		if err := os.MkdirAll(filepath.Dir(lockPath), 0o700); err != nil {
			return err
		}
	}
	if credentialSaveBeforeLockHook != nil {
		credentialSaveBeforeLockHook()
	}
	return cliutil.WithFileLock(lockPath, func() error {
		resolved, credsPath, lockedLock, err := c.credentialSavePlan(requested)
		if err != nil {
			return err
		}
		if lockedLock != lockPath {
			return fmt.Errorf("profile changed while locking credentials")
		}
		if c.explicitConfig {
			c.Path = resolved
		}
		return c.saveCredentialsThenConfigLocked(credsPath)
	})
}

func (c *Config) retargetExplicitConfig() error {
	if !c.explicitConfig {
		return nil
	}
	resolved, err := cliutil.ResolveConfigFilePath(c.Path)
	if err != nil {
		return err
	}
	c.Path = resolved
	return nil
}

func (c *Config) credentialSavePlan(requested string) (configPath, credsPath, lockPath string, err error) {
	configPath = requested
	if c.explicitConfig {
		configPath, err = cliutil.ResolveConfigFilePath(requested)
		if err != nil {
			return "", "", "", err
		}
		credsPath, err = cliutil.CredentialsFilePathForConfig(configPath)
	} else {
		credsPath, err = cliutil.CredentialsFilePath()
	}
	if err != nil {
		return "", "", "", err
	}
	if !c.explicitConfig {
		return configPath, credsPath, credsPath, nil
	}
	lockPath, err = explicitProfileLockPath(credsPath)
	if err != nil {
		return "", "", "", err
	}
	return configPath, credsPath, lockPath, nil
}

// Every config that shares one credentials file has to take the same lock.
// The lock file sits in the profile directory: a lock under data/ is created
// by following a symlinked data directory.
func explicitProfileLockPath(credsPath string) (string, error) {
	dataDir := filepath.Dir(credsPath)
	if filepath.Base(dataDir) != "data" {
		return "", fmt.Errorf("unexpected credentials path %s", credsPath)
	}
	return filepath.Join(filepath.Dir(dataDir), ".credentials"), nil
}

func (c *Config) saveCredentialsThenConfigLocked(credsPath string) error {
	if c.explicitConfig {
		return c.saveExplicitCredentialsThenConfig(credsPath)
	}
	snap, err := snapshotCredentialsFile(credsPath)
	if err != nil {
		return err
	}
	if err := c.saveCredentialsFirst(credsPath); err != nil {
		return err
	}
	if err := c.save(); err != nil {
		if restoreErr := restoreCredentialsFile(snap); restoreErr != nil {
			return fmt.Errorf("%w (credentials file %s was replaced; restore failed: %v)", err, credsPath, restoreErr)
		}
		return err
	}
	return nil
}

func (c *Config) saveExplicitCredentialsThenConfig(credsPath string) error {
	snap, err := snapshotExplicitCredentials(credsPath)
	if err != nil {
		return err
	}
	if err := c.saveCredentialsFirst(credsPath); err != nil {
		return err
	}
	if err := c.save(); err != nil {
		if restoreErr := restoreExplicitCredentials(snap); restoreErr != nil {
			return fmt.Errorf("%w (credentials file %s was replaced; restore failed: %v)", err, credsPath, restoreErr)
		}
		return err
	}
	return nil
}

func snapshotExplicitCredentials(path string) (credentialsSnapshot, error) {
	data, err := cliutil.ReadExplicitCredentialBytes(path)
	if err != nil {
		if os.IsNotExist(err) {
			return credentialsSnapshot{path: path, missing: true}, nil
		}
		return credentialsSnapshot{}, err
	}
	return credentialsSnapshot{path: path, data: data, perm: 0o600}, nil
}

func restoreExplicitCredentials(snap credentialsSnapshot) error {
	if snap.path == "" {
		return fmt.Errorf("credentials path unknown")
	}
	if snap.missing {
		return cliutil.RemoveExplicitCredentials(snap.path)
	}
	return cliutil.WriteExplicitCredentialBytes(snap.path, snap.data)
}

func snapshotCredentialsFile(path string) (credentialsSnapshot, error) {
	snap := credentialsSnapshot{path: path}
	info, err := os.Lstat(path)
	if err != nil {
		if os.IsNotExist(err) {
			snap.missing = true
			return snap, nil
		}
		return credentialsSnapshot{}, err
	}
	if info.Mode()&os.ModeSymlink != 0 {
		target, err := os.Readlink(path)
		if err != nil {
			return credentialsSnapshot{}, err
		}
		snap.symlinkTarget = target
	}
	targetInfo, err := os.Stat(path)
	if err != nil {
		return credentialsSnapshot{}, err
	}
	snap.perm = targetInfo.Mode().Perm()
	data, err := os.ReadFile(filepath.Clean(path)) // #nosec G304 -- app-owned credentials path from cliutil.DataDir.
	if err != nil {
		return credentialsSnapshot{}, err
	}
	snap.data = data
	return snap, nil
}

func restoreCredentialsFile(snap credentialsSnapshot) error {
	if snap.path == "" {
		return fmt.Errorf("credentials path unknown")
	}
	if snap.missing {
		if err := os.Remove(snap.path); err != nil && !os.IsNotExist(err) {
			return err
		}
		return nil
	}
	if snap.symlinkTarget != "" {
		if err := os.Remove(snap.path); err != nil && !os.IsNotExist(err) {
			return err
		}
		if err := os.Symlink(snap.symlinkTarget, snap.path); err != nil {
			return err
		}
		if err := os.WriteFile(snap.path, snap.data, 0o600); err != nil {
			return err
		}
		if resolved, err := filepath.EvalSymlinks(snap.path); err == nil && snap.perm != 0 {
			if err := os.Chmod(resolved, snap.perm); err != nil {
				return err
			}
		}
		return nil
	}
	mode := snap.perm
	if mode == 0 {
		mode = 0o600
	}
	if err := cliutil.AtomicWritePrivateFile(snap.path, snap.data, mode, 0o700); err != nil {
		return err
	}
	return os.Chmod(snap.path, mode)
}

// Explicit login flags intentionally opt these fields out of environment-value
// filtering; capture their provenance before applying any fallback.
func (c *Config) MarkCredentialsExplicit(clientID, clientSecret bool) {
	if clientID {
		delete(c.envOverrides, "ClientID")
	}
	if clientSecret {
		delete(c.envOverrides, "ClientSecret")
	}
}

func (c *Config) SaveTokens(clientID, clientSecret, accessToken, refreshToken string, expiry time.Time) error {
	c.ClientID = clientID
	c.ClientSecret = clientSecret
	c.AccessToken = accessToken
	c.RefreshToken = refreshToken
	c.TokenExpiry = expiry
	delete(c.envOverrides, "AccessToken")
	delete(c.envOverrides, "RefreshToken")
	delete(c.envOverrides, "TokenExpiry")
	c.updateFileConfigField("ClientID")
	c.updateFileConfigField("ClientSecret")
	c.updateFileConfigField("AccessToken")
	c.updateFileConfigField("RefreshToken")
	c.updateFileConfigField("TokenExpiry")
	return c.saveCredentialsThenConfig()
}

// SaveCredential persists a single API credential to the field that
// AuthHeader() consults for api_key auth. Writing to AccessToken (the
// bearer slot) would silently no-op since AuthHeader() reads the env-var-
// derived field, not AccessToken, when Auth.Type == "api_key".
//
// The clears precede the assignment so a canonical env-var whose placeholder
// collides with a builtin tag (e.g. an env var named XXX_ACCESS_TOKEN
// resolving to the AccessToken field) ends up holding the new token.
func (c *Config) SaveCredential(token string) error {
	c.AuthHeaderVal = ""
	c.AccessToken = ""
	// Pair each builtin-field zeroing with an envOverrides delete, like
	// ClearTokens/SaveBearerToken: if an env var's placeholder collides with the
	// AuthHeaderVal/AccessToken builtin tag, the override would otherwise survive
	// and configForSave would restore the stale on-disk value instead of "".
	delete(c.envOverrides, "AuthHeaderVal")
	delete(c.envOverrides, "AccessToken")
	c.updateFileConfigField("AuthHeaderVal")
	c.updateFileConfigField("AccessToken")
	c.RichAuthApiKey = token
	delete(c.envOverrides, "RichAuthApiKey")
	c.updateFileConfigField("RichAuthApiKey")
	return c.saveCredentialsThenConfig()
}

func (c *Config) ClearTokens() error {
	// AuthHeader() falls back to the env-var-derived fields when AuthHeaderVal
	// and AccessToken are empty, so dropping the working credential requires
	// zeroing every emitted credential field, not just the OAuth trio.
	// ClientID/ClientSecret persist to disk via SaveTokens for the oauth2
	// and oauth2-cc flows, so logout must wipe them too; otherwise
	// `auth login` can re-mint a new access token unattended.
	c.AuthHeaderVal = ""
	c.AccessToken = ""
	c.RefreshToken = ""
	c.TokenExpiry = time.Time{}
	c.ClientID = ""
	c.ClientSecret = ""
	delete(c.envOverrides, "AuthHeaderVal")
	delete(c.envOverrides, "AccessToken")
	delete(c.envOverrides, "RefreshToken")
	delete(c.envOverrides, "TokenExpiry")
	delete(c.envOverrides, "ClientID")
	delete(c.envOverrides, "ClientSecret")
	c.updateFileConfigField("AuthHeaderVal")
	c.updateFileConfigField("AccessToken")
	c.updateFileConfigField("RefreshToken")
	c.updateFileConfigField("TokenExpiry")
	c.updateFileConfigField("ClientID")
	c.updateFileConfigField("ClientSecret")
	c.RichAuthApiKey = ""
	delete(c.envOverrides, "RichAuthApiKey")
	c.updateFileConfigField("RichAuthApiKey")
	c.RichAuthClientId = ""
	delete(c.envOverrides, "RichAuthClientId")
	c.updateFileConfigField("RichAuthClientId")
	c.RichAuthClientSecret = ""
	delete(c.envOverrides, "RichAuthClientSecret")
	c.updateFileConfigField("RichAuthClientSecret")
	c.RichAuthSessionCookie = ""
	delete(c.envOverrides, "RichAuthSessionCookie")
	c.updateFileConfigField("RichAuthSessionCookie")
	c.RichAuthOptionalToken = ""
	delete(c.envOverrides, "RichAuthOptionalToken")
	c.updateFileConfigField("RichAuthOptionalToken")
	c.RichAuthBotToken = ""
	delete(c.envOverrides, "RichAuthBotToken")
	c.updateFileConfigField("RichAuthBotToken")
	c.RichAuthUserToken = ""
	delete(c.envOverrides, "RichAuthUserToken")
	c.updateFileConfigField("RichAuthUserToken")
	if c.AgentcookieManagedByExternalStore() {
		c.markAgentcookieManaged()
		// save() persists the full config (credential fields included) for
		// agentcookie-managed stores, so the zeroed fields must be written
		// back; returning early would leave the secrets on disk.
		return c.save()
	}
	if c.explicitConfig {
		credsPath, err := c.credentialsFilePath()
		if err != nil {
			return err
		}
		if err := cliutil.RemoveExplicitCredentials(credsPath); err != nil {
			return err
		}
	} else if err := cliutil.RemoveCredentials(); err != nil {
		return err
	}
	return c.save()
}

func (c *Config) dropUntrustedTLSSettings() {
	if c == nil {
		return
	}
	if strings.TrimSpace(c.CACert) == "" && strings.TrimSpace(c.TLSServerName) == "" {
		return
	}
	where := strings.TrimSpace(c.Path)
	if where == "" {
		where = "config file"
	}
	fmt.Fprintf(os.Stderr, "warning: ignoring ca_cert and tls_server_name from %s because other users can change it\n", where)
	c.CACert = ""
	c.TLSServerName = ""
}

func (c *Config) markEnvOverride(field string) {
	if c.envOverrides == nil {
		c.envOverrides = map[string]bool{}
	}
	c.envOverrides[field] = true
}

func (c *Config) SetCACert(value string) {
	c.CACert = value
	c.markEnvOverride("CACert")
}

func (c *Config) SetTLSServerName(value string) {
	c.TLSServerName = value
	c.markEnvOverride("TLSServerName")
}

// cloneStringMap returns an independent copy of m (nil stays nil). The fileConfig
// snapshot must not share reference-type map fields (such as Headers) with the
// live config, or a later mutation to one would silently track in the other.
func cloneStringMap(m map[string]string) map[string]string {
	if m == nil {
		return nil
	}
	out := make(map[string]string, len(m))
	for k, v := range m {
		out[k] = v
	}
	return out
}

func (c *Config) snapshotFileConfig() {
	snapshot := *c
	snapshot.envOverrides = nil
	snapshot.fileConfig = nil
	// *c is a shallow copy: map fields are reference types, so the snapshot would
	// share them with c and silently track later mutations, defeating the
	// isolation this snapshot exists to provide. Clone them.
	snapshot.Headers = cloneStringMap(c.Headers)
	c.fileConfig = &snapshot
}

func (c *Config) configForSave() Config {
	out := *c
	if c.fileConfig != nil {
		if c.envOverrides["CACert"] {
			out.CACert = c.fileConfig.CACert
		}
		if c.envOverrides["TLSServerName"] {
			out.TLSServerName = c.fileConfig.TLSServerName
		}
		if c.envOverrides["RichAuthApiKey"] {
			out.RichAuthApiKey = c.fileConfig.RichAuthApiKey
		}
		if c.envOverrides["RichAuthClientId"] {
			out.RichAuthClientId = c.fileConfig.RichAuthClientId
		}
		if c.envOverrides["RichAuthClientSecret"] {
			out.RichAuthClientSecret = c.fileConfig.RichAuthClientSecret
		}
		if c.envOverrides["RichAuthSessionCookie"] {
			out.RichAuthSessionCookie = c.fileConfig.RichAuthSessionCookie
		}
		if c.envOverrides["RichAuthOptionalToken"] {
			out.RichAuthOptionalToken = c.fileConfig.RichAuthOptionalToken
		}
		if c.envOverrides["RichAuthBotToken"] {
			out.RichAuthBotToken = c.fileConfig.RichAuthBotToken
		}
		if c.envOverrides["RichAuthUserToken"] {
			out.RichAuthUserToken = c.fileConfig.RichAuthUserToken
		}
	}
	out.envOverrides = nil
	out.fileConfig = nil
	return out
}

func (c *Config) updateFileConfigField(field string) {
	if c.fileConfig == nil || c.envOverrides[field] {
		return
	}
	switch field {
	case "AuthHeaderVal":
		c.fileConfig.AuthHeaderVal = c.AuthHeaderVal
	case "AccessToken":
		c.fileConfig.AccessToken = c.AccessToken
	case "RefreshToken":
		c.fileConfig.RefreshToken = c.RefreshToken
	case "TokenExpiry":
		c.fileConfig.TokenExpiry = c.TokenExpiry
	case "ClientID":
		c.fileConfig.ClientID = c.ClientID
	case "ClientSecret":
		c.fileConfig.ClientSecret = c.ClientSecret
	case "RichAuthApiKey":
		c.fileConfig.RichAuthApiKey = c.RichAuthApiKey
	case "RichAuthClientId":
		c.fileConfig.RichAuthClientId = c.RichAuthClientId
	case "RichAuthClientSecret":
		c.fileConfig.RichAuthClientSecret = c.RichAuthClientSecret
	case "RichAuthSessionCookie":
		c.fileConfig.RichAuthSessionCookie = c.RichAuthSessionCookie
	case "RichAuthOptionalToken":
		c.fileConfig.RichAuthOptionalToken = c.RichAuthOptionalToken
	case "RichAuthBotToken":
		c.fileConfig.RichAuthBotToken = c.RichAuthBotToken
	case "RichAuthUserToken":
		c.fileConfig.RichAuthUserToken = c.RichAuthUserToken
	}
}

func (c *Config) save() error {
	// A symlink --config must stay a symlink. Replacing it would make the next
	// load look for credentials beside the link instead of the resolved profile.
	if err := c.retargetExplicitConfig(); err != nil {
		return err
	}
	persisted := c.configForSave()
	var persist any = persisted
	if !c.AgentcookieManagedByExternalStore() {
		persist = persisted.persisted()
	}
	data, err := toml.Marshal(persist)
	if err != nil {
		return fmt.Errorf("marshaling config: %w", err)
	}
	if err := cliutil.AtomicWritePrivateFile(c.Path, data, 0o600, 0o700); err != nil {
		return err
	}
	c.scrubLegacyCredentials()
	if !c.AgentcookieManagedByExternalStore() {
		persisted.clearCredentialFields()
	}
	c.fileConfig = &persisted
	c.fileConfig.envOverrides = nil
	c.fileConfig.fileConfig = nil
	// persisted shares its map fields with c (configForSave shallow-copies *c),
	// so isolate the stored fileConfig the same way snapshotFileConfig does;
	// otherwise later mutations to c's maps leak into the on-disk snapshot.
	c.fileConfig.Headers = cloneStringMap(c.fileConfig.Headers)
	return nil
}
func (c *Config) scrubLegacyCredentials() {
	if c.legacySourcePath == "" || c.legacySourcePath == c.Path {
		return
	}
	if c.AgentcookieManagedByExternalStore() {
		return
	}
	data, err := os.ReadFile(c.legacySourcePath)
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "warning: cannot read legacy config to scrub credentials: %v\n", err)
		}
		return
	}
	var legacy Config
	if err := toml.Unmarshal(data, &legacy); err != nil {
		fmt.Fprintf(os.Stderr, "warning: cannot parse legacy config to scrub credentials: %v\n", err)
		return
	}
	legacy.clearCredentialFields()
	scrubbed := legacy.persisted()
	scrubbedData, err := toml.Marshal(scrubbed)
	if err != nil {
		fmt.Fprintf(os.Stderr, "warning: cannot marshal scrubbed legacy config: %v\n", err)
		return
	}
	if err := cliutil.AtomicWritePrivateFile(c.legacySourcePath, scrubbedData, 0o600, 0o700); err != nil {
		fmt.Fprintf(os.Stderr, "warning: cannot write scrubbed legacy config: %v\n", err)
	}
}

type persistedConfig struct {
	BaseURL       string            `toml:"base_url"`
	CACert        string            `toml:"ca_cert,omitempty"`
	TLSServerName string            `toml:"tls_server_name,omitempty"`
	Headers       map[string]string `toml:"headers,omitempty"`
}

func (c *Config) persisted() persistedConfig {
	return persistedConfig{
		BaseURL:       c.BaseURL,
		CACert:        c.CACert,
		TLSServerName: c.TLSServerName,
		Headers:       c.Headers,
	}
}

// Ensure strings import is used
var _ = strings.ReplaceAll
